for key, value in data.items():
    # Create the placeholder key with double braces: {{key}}
    # In f-strings, {{ produces a literal { and }} produces a literal }
    placeholder = f'{{{{{key}}}}}'

    if key == '참석자수':
        # Strip non-digit characters, keep digits only
        transformed = re.sub(r'[^0-9]', '', str(value))
        replacements[placeholder] = transformed
        print(f"  {placeholder} -> '{transformed}' (digits only)")
    elif key == '만족도':
        # Extract numeric value and rewrite format
        match = re.match(r'([0-9.]+)', str(value))
        if match:
            score = match.group(1)
            transformed = f"{score}점 (5.0점 만점)"
        else:
            transformed = value
        replacements[placeholder] = transformed
        print(f"  {placeholder} -> '{transformed}' (formatted score)")
    elif key == '종합의견':
        # Append additional text
        transformed = f"{value} 후속 심화반 검토 요망."
        replacements[placeholder] = transformed
        print(f"  {placeholder} -> '{transformed}' (appended text)")
    else:
        # All other placeholders - substitute as-is
        replacements[placeholder] = str(value)
        print(f"  {placeholder} -> '{value}' (as-is)")
